@libentry()
@triton.jit
def _coo_bounds_kernel(
    indices, partial, nnz, stride_d, stride_n, tiles, BLOCK: tl.constexpr
):
    """Per-dimension coordinate bounds for one tile of the coordinate matrix.

    Grid is 1D (``sparse_dim * tiles``): the generic 2D ``(sparse_dim, tiles)``
    layout exceeds the 255 grid.y limit once nnz passes ``255 * BLOCK``.
    """
    pid = tl.program_id(0)
    d = pid // tiles
    tile = pid % tiles
    offsets = tile * BLOCK + tl.arange(0, BLOCK)
    x = tl.load(
        indices + d * stride_d + offsets * stride_n,
        offsets < nnz,
        other=0,
    )
    hi = tl.max(tl.where(offsets < nnz, x, -1), 0)
    lo = tl.min(tl.where(offsets < nnz, x, 9223372036854775807), 0)
    tl.store(partial + (d * tiles + tile) * 2, hi)
    tl.store(partial + (d * tiles + tile) * 2 + 1, lo)


@libentry()
@triton.jit
def _coo_finish_bounds_kernel(partial, bounds, tiles, BLOCK: tl.constexpr):
    """Combine the per-tile bounds of one dimension into a single (hi, lo)."""
    d = tl.program_id(0)
    offsets = tl.arange(0, BLOCK)
    hi = tl.full((BLOCK,), -1, tl.int64)
    lo = tl.full((BLOCK,), 9223372036854775807, tl.int64)
    for start in range(tl.cdiv(tiles, BLOCK)):
        tile = start * BLOCK + offsets
        hi = tl.maximum(
            hi,
            tl.load(partial + (d * tiles + tile) * 2, tile < tiles, other=-1),
        )
        lo = tl.minimum(
            lo,
            tl.load(
                partial + (d * tiles + tile) * 2 + 1,
                tile < tiles,
                other=9223372036854775807,
            ),
        )
    tl.store(bounds + d * 2, tl.max(hi, 0))
    tl.store(bounds + d * 2 + 1, tl.min(lo, 0))


def _get_bounds_scratch(device, sparse_dim, tiles):
    """Single-entry scratch reuse for the bounds-reduction buffers.

    ``_infer_size`` always ends in a synchronous ``tolist()`` read of the
    reduction output, so a completed call has fully consumed both buffers and
    the next same-shape call can overwrite them in place. A miss falls back
    to fresh allocations, so the cache can never change behavior — it only
    removes the per-call allocator round trips on repeat shapes. Kept as a
    single entry so alternating shapes degrade to the plain path instead of
    growing a device-memory cache.
    """
    key = (device.type, device.index, sparse_dim, tiles)
    scratch = _BOUNDS_SCRATCH.get(key)
    if scratch is None:
        scratch = (
            torch.empty((sparse_dim, tiles, 2), dtype=torch.int64, device=device),
            torch.empty((sparse_dim, 2), dtype=torch.int64, device=device),
        )
        _BOUNDS_SCRATCH.clear()
        _BOUNDS_SCRATCH[key] = scratch
    return scratch


# Below this many partial pairs (sparse_dim * tiles) the host-side combine over
# ``partial.tolist()`` beats a second kernel launch: the tolist sync latency
# (~16us) is size-insensitive at these payloads, so it absorbs the combine for
# free while skipping one ~16us launch. Larger reductions keep the finish
# kernel so the host never iterates long lists.
_HOST_COMBINE_MAX_PARTIALS = 256


def _infer_size(indices, values):
    """Infer the sparse extents from the coordinate matrix (device reduction)."""
    sparse_dim, nnz = indices.shape
    dense_shape = list(values.shape[1:]) if values.ndim else []
    if not sparse_dim or not nnz:
        return [0] * sparse_dim + dense_shape

    tiles = triton.cdiv(nnz, _BLOCK)
    partial, bounds = _get_bounds_scratch(indices.device, sparse_dim, tiles)
    host_combine = sparse_dim * tiles <= _HOST_COMBINE_MAX_PARTIALS
    with torch_device_fn.device(indices.device):
        _coo_bounds_kernel[(sparse_dim * tiles,)](
            indices, partial, nnz, *indices.stride(), tiles, BLOCK=_BLOCK
        )
        if host_combine:
            # Tensor dimensions are host metadata; this synchronization is
            # part of the operator and must be included in its end-to-end
            # benchmark. reshape(-1) is a metadata view on the contiguous
            # partial buffer and tolist must flatten before slicing.
            flat = partial.reshape(-1).tolist()
        else:
            _coo_finish_bounds_kernel[(sparse_dim,)](
                partial,
                bounds,
                tiles,
                BLOCK=min(_BLOCK, triton.next_power_of_2(tiles)),
            )
            flat = bounds.reshape(-1).tolist()

    if host_combine:
        row_width = tiles * 2
        pairs = []
        for d in range(sparse_dim):
            row = flat[d * row_width : (d + 1) * row_width]
            pairs.append((max(row[0::2]), min(row[1::2])))
    else:
        pairs = [(flat[2 * d], flat[2 * d + 1]) for d in range(sparse_dim)]

    extents = []
    for d, (hi, lo) in enumerate(pairs):
        if lo < 0:
            raise RuntimeError(f"found negative index {lo} for dim {d}")
        if hi == _I64_MAX:
            raise RuntimeError("inferred sparse size overflows int64")
        extents.append(hi + 1)
    return extents + dense_shape


class _CooValuesCopy(torch.autograd.Function):
    @staticmethod
    def forward(ctx, values, dtype, device):
        ctx.dtype = values.dtype
        ctx.device = values.device
        if device.type == "cpu":
            return to_copy(values, dtype=dtype, device=device)
        with torch_device_fn.device(device):
            return to_copy(values, dtype=dtype, device=device)

    @staticmethod
    def backward(ctx, grad):
        return _CooValuesCopy.apply(grad, ctx.dtype, ctx.device), None, None


def sparse_coo_tensor(
    indices,
    values,
    size=None,
    *,
    dtype=None,
    layout=None,
    device=None,
    pin_memory=None,
    is_coalesced=None,
):
    """Construct COO from tensors, with explicit or Triton-inferred size.

    Matching options preserve storage aliasing. Conversions use FlagGems
    to_copy (native transfer primitives for cross-device copies); complex
    index normalization routes through CPU because on-device complex casts
    abort the process (torch_gcu P21).
    """
    logger.debug("GEMS_ENFLAME SPARSE_COO_TENSOR")
    if layout is not None and layout != torch.sparse_coo:
        raise RuntimeError(f"expected sparse layout, but got layout {layout}")
    if not isinstance(indices, torch.Tensor) or not isinstance(values, torch.Tensor):
        raise TypeError("indices and values must be tensors")
    if indices.layout != torch.strided:
        raise RuntimeError("expected indices to be a dense tensor")
    if values.layout != torch.strided:
        raise RuntimeError("expected values to be a dense tensor")
    if indices.ndim != 2:
        raise RuntimeError("indices must be sparse_dim x nnz")
    nnz = values.shape[0] if values.ndim else 1
    if indices.shape[1] != nnz:
        raise RuntimeError("indices and values must have the same nnz")
    if device is None and indices.device != values.device:
        raise RuntimeError("indices and values must be on the same device")

    target = torch.device(device) if device is not None else values.device
    if target.type == "cpu":
        raise NotImplementedError("Triton COO size inference requires a device tensor")
    if target.index is None:
        target = torch.device(target.type, torch_device_fn.current_device())

    if size is None and pin_memory:
        # Inferred-constructor pinning differs between PyTorch builds. Preserve
        # the installed public factory's behavior rather than suppressing True.
        result = torch.sparse_coo_tensor(
            indices, values, dtype=dtype, device=target, pin_memory=True
        )
        if is_coalesced is None:
            return result
        # Older public inferred bindings do not accept is_coalesced. Assemble
        # from the original values to preserve their autograd connection.
        return torch.sparse_coo_tensor(
            indices,
            values,
            result.shape,
            dtype=dtype,
            device=target,
            is_coalesced=is_coalesced,
        )
    if indices.dtype != torch.int64 or indices.device != target:
        if indices.is_complex():
            # On-device complex casts abort the process (topsatenCopy, P21);
            # the CPU path applies the same real-part truncation the native
            # factory uses when it normalizes complex indices.
            indices = indices.to("cpu").to(torch.int64).to(target)
        else:
            with torch_device_fn.device(target):
                indices = to_copy(indices, dtype=torch.int64, device=target)
    if values.device != target or (dtype is not None and values.dtype != dtype):
        values = _CooValuesCopy.apply(values, dtype, target)

    # Normalize the coordinate matrix to int64 on the target device; the
    # factory requires int64 coordinates. Conversions run through the FlagGems
    # copy kernel so the same code path serves every source dtype.
    if indices.dtype != torch.int64 or indices.device != target:
        with torch_device_fn.device(target):
            indices = to_copy(indices, dtype=torch.int64, device=target)
    if values.device != target:
        # Only the placement is normalized here; the requested output dtype is
        # left to the factory so dtype selection (including the platform's
        # handling of non-contiguous values) matches the aten reference.
        with torch_device_fn.device(target):
            values = to_copy(values, dtype=values.dtype, device=target)

    if size is None:
        size = _infer_size(indices, values)
    else:
        for extent in size:
            if extent < 0:
                raise RuntimeError(
                    f"sparse COO size contains a negative dimension: {extent}"
                )
    # The public factory selects the sparse backend via BackendSelect. Our two
    # registrations are on the dense device key, so assembly does not recurse.
    return torch.sparse_coo_tensor(
        indices,
        values,
        size,
        dtype=dtype,
        device=target,
        # Inferred pin_memory=True is handled above by the public factory.
        pin_memory=bool(pin_memory),
        is_coalesced=is_coalesced,
    )


